//! Bindings for Hyprland's own protocols, generated by
//! `wayland-scanner` as `wayland-protocols` does. Their XML is in
//! `protocols/hyprland`, from hyprwm/hyprland-protocols v0.8.0 (commit
//! 044a434), under the BSD-3-Clause license beside it.

macro_rules! hyprland_protocol {
  ($name:ident, $path:literal) => {
    pub(crate) mod $name {
      #![allow(dead_code, non_camel_case_types, unused_imports, missing_docs)]
      #![allow(non_upper_case_globals, clippy::all)]

      use smithay_client_toolkit::reexports::client as wayland_client;
      use wayland_client::protocol::*;

      pub(crate) mod __interfaces {
        use smithay_client_toolkit::reexports::client::backend as wayland_backend;
        use smithay_client_toolkit::reexports::client::protocol::__interfaces::*;
        wayland_scanner::generate_interfaces!($path);
      }
      use self::__interfaces::*;

      wayland_scanner::generate_client_code!($path);
    }
  };
}

hyprland_protocol!(
  global_shortcuts,
  "protocols/hyprland/hyprland-global-shortcuts-v1.xml"
);
hyprland_protocol!(focus_grab, "protocols/hyprland/hyprland-focus-grab-v1.xml");
hyprland_protocol!(surface, "protocols/hyprland/hyprland-surface-v1.xml");
